function weightedLinesThresholdFile(links, k) {
  const a=links; let out=[];
  const n=a.length,dist=Array(n).fill(Infinity),heap=[];if(n){dist[0]=0;heap.push([0,0]);}while(heap.length){const [cost,u]=heap[0],last=heap.pop();if(heap.length){heap[0]=last;let i=0;while(true){let j=i,l=i*2+1,r=l+1;if(l<heap.length&&heap[l][0]<heap[j][0])j=l;if(r<heap.length&&heap[r][0]<heap[j][0])j=r;if(j===i)break;[heap[i],heap[j]]=[heap[j],heap[i]];i=j;}}if(cost!==dist[u])continue;for(let v=0;v<n;v++)if(a[u][v]>0&&cost+a[u][v]<dist[v]){dist[v]=cost+a[u][v];heap.push([dist[v],v]);let i=heap.length-1;while(i>0){const p=(i-1)>>1;if(heap[p][0]<=heap[i][0])break;[heap[p],heap[i]]=[heap[i],heap[p]];i=p;}}}out=dist.map(x=>Number.isFinite(x)?x:-1);
  return out.filter(x=>x>=k).length;
}

